package io.knowledgebrain.brainquery;
import java.util.*;
import java.nio.charset.StandardCharsets;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="BRAIN_TEST_QUERY_DATABASE_URL",matches=".+")
class BrainProjectionIntegrationTest {
 static UUID id(){var u=UUID.randomUUID();return new UUID((u.getMostSignificantBits()&~0xf000L)|0x7000L,u.getLeastSignificantBits());}
 BrainProjectionStore store;JdbcTemplate sql;UUID space;String schema;
 @BeforeEach void setup(){var d=new PGSimpleDataSource();d.setURL(System.getenv("BRAIN_TEST_QUERY_DATABASE_URL"));d.setUser("brain_brainquery");d.setPassword(System.getenv("BRAIN_TEST_QUERY_DATABASE_PASSWORD"));schema="brain_network_test_"+UUID.randomUUID().toString().replace("-","");d.setCurrentSchema(schema);Flyway.configure().dataSource(d).schemas(schema).locations("classpath:db/migration").load().migrate();store=new BrainProjectionStore(d);sql=new JdbcTemplate(d);space=id();}
 @AfterEach void cleanup(){if(schema!=null){if(!schema.matches("brain_network_test_[0-9a-f]{32}"))throw new IllegalStateException("Invalid test schema");sql.execute("DROP SCHEMA "+schema+" CASCADE");}}
 BrainProjection.Input input(String kind,UUID id,long version,String state,String title,String body,List<BrainProjection.Ref> refs){return new BrainProjection.Input(id(),id,space,kind,version,state,"PRIVATE",state.equals("RETIRED")?"":title,state.equals("RETIRED")?"":body,refs,"a".repeat(32));}
 void stage(BrainProjection.Input n){store.stage(n,n.toString().getBytes(StandardCharsets.UTF_8));}
 BrainProjectionStore.Document document(String kind,UUID id){return store.document(new BrainProjectionStore.Key(kind,id),1);}
 @Test void batchExternalFailureLeavesEveryDurableMarkerPendingForIdempotentRetry(){var a=id();var b=id();stage(input("NOTE",a,1,"ACTIVE","Batch A","",List.of()));stage(input("NOTE",b,1,"ACTIVE","Batch B","",List.of()));var keys=List.of(new BrainProjectionStore.Key("NOTE",a),new BrainProjectionStore.Key("NOTE",b));var graph=org.mockito.Mockito.mock(BrainGraphStore.class);var search=org.mockito.Mockito.mock(NoteSearchClient.class);org.mockito.Mockito.doThrow(new NoteSearchClient.Unavailable()).doNothing().when(search).applyBrainBatch(org.mockito.ArgumentMatchers.anyList());assertThrows(NoteSearchClient.Unavailable.class,()->store.projectBatch(keys,graph,search));assertEquals(0,sql.queryForObject("SELECT sum(applied_sequence) FROM brain_network_work WHERE entity_id IN (?,?)",Long.class,a,b));store.projectBatch(keys,graph,search);assertEquals(0,sql.queryForObject("SELECT count(*) FROM brain_network_work WHERE entity_id IN (?,?) AND applied_sequence<sequence",Long.class,a,b));org.mockito.Mockito.verify(graph,org.mockito.Mockito.times(2)).applyBatch(org.mockito.ArgumentMatchers.anyList());}
 @Test void claimBeforeConceptsThenRenameAndRetirementFanOutWithoutCanonicalClaimRevision(){var s=id();var p=id();var o=id();var claim=id();var refs=List.of(new BrainProjection.Ref(claim,"SUBJECT","CONCEPT",s),new BrainProjection.Ref(claim,"PREDICATE","CONCEPT",p),new BrainProjection.Ref(claim,"OBJECT","CONCEPT",o));stage(input("CLAIM",claim,1,"ACTIVE","","",refs));assertFalse(document("CLAIM",claim).visible());stage(input("CONCEPT",s,1,"ACTIVE","Java","",List.of()));stage(input("CONCEPT",p,1,"ACTIVE","supports","",List.of()));stage(input("CONCEPT",o,1,"ACTIVE","threads","",List.of()));assertEquals("Java → supports → threads",document("CLAIM",claim).title());long sequence=sql.queryForObject("SELECT sequence FROM brain_network_work WHERE kind='CLAIM' AND entity_id=?",Long.class,claim);stage(input("CONCEPT",o,2,"ACTIVE","virtual threads","",List.of()));assertEquals("Java → supports → virtual threads",document("CLAIM",claim).title());assertTrue(sequence<sql.queryForObject("SELECT sequence FROM brain_network_work WHERE kind='CLAIM' AND entity_id=?",Long.class,claim));assertEquals(1,document("CLAIM",claim).canonicalVersion());stage(input("CONCEPT",p,2,"RETIRED","","",List.of()));assertFalse(document("CLAIM",claim).visible());assertEquals("",document("CLAIM",claim).title());assertEquals(1,sql.queryForObject("SELECT version FROM brain_network_snapshot WHERE kind='CLAIM' AND entity_id=?",Long.class,claim));}
 @Test void independentNoteLinksAndConceptReferencesRequireOwnSpaceAndCurrentPrivateConcept(){var note=id();var concept=id();var link=id();stage(input("NOTE_CONCEPTS",note,8,"ACTIVE","","",List.of(new BrainProjection.Ref(link,"NOTE_CONCEPT","CONCEPT",concept))));assertFalse(document("NOTE",note).visible());stage(input("NOTE",note,2,"ACTIVE","Note","body",List.of()));assertTrue(document("NOTE",note).refs().isEmpty());stage(input("CONCEPT",concept,1,"ACTIVE","Linked concept","",List.of()));assertEquals(1,document("NOTE",note).refs().size());assertTrue(document("NOTE",note).text().contains("Linked concept"));stage(input("NOTE",note,3,"ACTIVE","Updated note","new body",List.of()));assertEquals(8,sql.queryForObject("SELECT version FROM brain_network_snapshot WHERE kind='NOTE_CONCEPTS' AND entity_id=?",Long.class,note));stage(input("LINKS",note,9,"RETIRED","","",List.of()));assertFalse(document("NOTE",note).visible());assertEquals("",document("NOTE",note).text());}
 @Test void publicOrForeignConceptReferencesNeverPopulatePrivateNoteOrClaimTitles(){var note=id();var concept=id();stage(input("NOTE",note,1,"ACTIVE","Mine","",List.of()));stage(input("NOTE_CONCEPTS",note,1,"ACTIVE","","",List.of(new BrainProjection.Ref(id(),"NOTE_CONCEPT","CONCEPT",concept))));var foreign=new BrainProjection.Input(id(),concept,id(),"CONCEPT",1,"ACTIVE","PRIVATE","Secret foreign","secret",List.of(),"a".repeat(32));stage(foreign);assertTrue(document("NOTE",note).refs().isEmpty());assertFalse(document("NOTE",note).text().contains("Secret"));var publicId=id();var publicInput=new BrainProjection.Input(id(),publicId,id(),"CONCEPT",1,"ACTIVE","PUBLIC","","",List.of(),"a".repeat(32));stage(publicInput);assertFalse(document("CONCEPT",publicId).visible());}
 @Test void byteDedupSameVersionConflictsSpaceReuseAndTombstonesAreDurable(){var id=id();var n=input("CONCEPT",id,2,"ACTIVE","New","",List.of());stage(n);stage(n);stage(input("CONCEPT",id,1,"ACTIVE","Old","",List.of()));assertEquals("New",document("CONCEPT",id).title());assertThrows(BrainProjectionStore.Conflict.class,()->stage(input("CONCEPT",id,2,"ACTIVE","Conflict","",List.of())));assertThrows(BrainProjectionStore.Conflict.class,()->stage(new BrainProjection.Input(n.eventId(),id,space,"CONCEPT",2,"ACTIVE","PRIVATE","New","",List.of(),"b".repeat(32))));stage(input("CONCEPT",id,3,"RETIRED","","",List.of()));assertThrows(BrainProjectionStore.Conflict.class,()->stage(input("CONCEPT",id,4,"ACTIVE","Resurrected","",List.of())));assertEquals("",document("CONCEPT",id).title());assertEquals(3,sql.queryForObject("SELECT version FROM brain_network_snapshot WHERE kind='CONCEPT' AND entity_id=?",Long.class,id));}
 @Test void recordLinksMayArriveFirstAndAdvanceIndependentlyWhileBodyArchiveWins(){for(var kind:List.of("BOOKMARK","QUESTION","DECISION")){var record=id();var concept=id();var relation=id();var refs=List.of(new BrainProjection.Ref(relation,"RECORD_CONCEPT","CONCEPT",concept));stage(input(kind+"_CONCEPTS",record,7,"ACTIVE","","",refs));assertFalse(document(kind,record).visible());stage(input(kind,record,2,"ACTIVE","Source","Own body",List.of()));assertTrue(document(kind,record).visible());assertTrue(document(kind,record).refs().isEmpty());stage(input("CONCEPT",concept,1,"ACTIVE","Linked name","",List.of()));assertEquals(refs,document(kind,record).refs());assertTrue(document(kind,record).text().contains("Linked name"));stage(input(kind,record,3,"ACTIVE","Renamed","Edited body",List.of()));assertEquals(3,document(kind,record).canonicalVersion());assertEquals(refs,document(kind,record).refs());stage(input(kind+"_CONCEPTS",record,8,"ACTIVE","","",List.of()));assertTrue(document(kind,record).refs().isEmpty());assertFalse(document(kind,record).text().contains("Linked name"));stage(input(kind,record,4,"RETIRED","","",List.of()));stage(input(kind+"_CONCEPTS",record,9,"ACTIVE","","",refs));var gone=document(kind,record);assertFalse(gone.visible());assertEquals("",gone.title());assertEquals("",gone.text());assertTrue(gone.refs().isEmpty());stage(input(kind,record,1,"ACTIVE","Late old event","secret",List.of()));assertFalse(document(kind,record).visible());}}
 @Test void conceptRenameAndRetirementFanOutToAllRecordKindsWithoutRewritingBodiesOrAssociationVersions(){var concept=id();var foreign=id();stage(new BrainProjection.Input(id(),foreign,id(),"CONCEPT",1,"ACTIVE","PRIVATE","ForeignSecret","",List.of(),"a".repeat(32)));stage(input("CONCEPT",concept,1,"ACTIVE","Before","",List.of()));for(var kind:List.of("BOOKMARK","DECISION","QUESTION")){var record=id();stage(input(kind,record,1,"ACTIVE",kind,"body",List.of()));stage(input(kind+"_CONCEPTS",record,3,"ACTIVE","","",List.of(new BrainProjection.Ref(id(),"RECORD_CONCEPT","CONCEPT",concept),new BrainProjection.Ref(id(),"RECORD_CONCEPT","CONCEPT",foreign))));assertFalse(document(kind,record).text().contains("ForeignSecret"));long before=sql.queryForObject("SELECT sequence FROM brain_network_work WHERE kind=? AND entity_id=?",Long.class,kind,record);stage(input("CONCEPT",concept,2+BrainProjection.RECORDS.stream().sorted().toList().indexOf(kind),"ACTIVE","Renamed"+kind,"",List.of()));assertTrue(document(kind,record).text().contains("Renamed"+kind));assertTrue(sql.queryForObject("SELECT sequence FROM brain_network_work WHERE kind=? AND entity_id=?",Long.class,kind,record)>before);assertEquals(1,document(kind,record).canonicalVersion());}stage(input("CONCEPT",concept,9,"RETIRED","","",List.of()));for(var key:store.pending(100))if(BrainProjection.RECORDS.contains(key.kind())){assertTrue(document(key.kind(),key.id()).refs().isEmpty());assertEquals("body",document(key.kind(),key.id()).text());}}
 @Test void typedIdsDoNotCollideAndForeignSourceOrChangedAssociationCannotOverwriteProjection(){var record=id();for(var kind:List.of("BOOKMARK","QUESTION","DECISION"))stage(input(kind,record,1,"ACTIVE",kind,"",List.of()));assertEquals(3,store.pending(100).size());var association=id();var links=new BrainProjection.Input(id(),record,space,"BOOKMARK_CONCEPTS",1,"ACTIVE","PRIVATE","","",List.of(),"a".repeat(32),association,1);stage(links);assertThrows(BrainProjectionStore.Conflict.class,()->stage(new BrainProjection.Input(id(),record,id(),"BOOKMARK_CONCEPTS",2,"ACTIVE","PRIVATE","","",List.of(),"a".repeat(32),association,1)));assertThrows(BrainProjectionStore.Conflict.class,()->stage(new BrainProjection.Input(id(),record,space,"BOOKMARK_CONCEPTS",2,"ACTIVE","PRIVATE","","",List.of(),"a".repeat(32),id(),1)));}

 @Test void literalTransitionRemovesObjectEdgeAndRetainsExactSearchValueAcrossReplay(){
  var subject=id();var predicate=id();var object=id();var claim=id();
  for(var c:List.of(subject,predicate,object))stage(input("CONCEPT",c,1,"ACTIVE","Concept","",List.of()));
  var refs=List.of(new BrainProjection.Ref(claim,"SUBJECT","CONCEPT",subject),new BrainProjection.Ref(claim,"PREDICATE","CONCEPT",predicate));
  var oldRefs=new ArrayList<>(refs);oldRefs.add(new BrainProjection.Ref(claim,"OBJECT","CONCEPT",object));
  var old=input("CLAIM",claim,1,"ACTIVE","","",oldRefs);stage(old);assertEquals(3,document("CLAIM",claim).refs().size());
  String exact="NUMBER: 9007199254740993.123456789012345678";var current=input("CLAIM",claim,2,"ACTIVE","",exact,refs);stage(current);stage(old);
  stage(input("CONCEPT",object,2,"RETIRED","","",List.of()));
  assertTrue(document("CLAIM",claim).visible());assertEquals(2,document("CLAIM",claim).refs().size());assertTrue(document("CLAIM",claim).text().contains(exact));assertTrue(document("CLAIM",claim).title().endsWith(exact));
  store=new BrainProjectionStore(sql.getDataSource());assertTrue(document("CLAIM",claim).text().contains(exact));stage(current);
  stage(input("CONCEPT",predicate,2,"RETIRED","","",List.of()));assertFalse(document("CLAIM",claim).visible());
 }
}
